import { getDevicesDictionary } from '@/i18n/requests';
import { Locale } from '@/i18n/routing';
import type { DimensionsConfig, FormatConfig } from '@/types/config';
import type { Format } from '@/utils/formats';

export function getCompressedFileName(
  orginalName: string,
  configName: string,
  format: string,
) {
  return getFileNameWithExtensionAndSuffix(
    orginalName,
    format,
    `-compressed-${configName}`,
  );
}

export function getFileNameWithExtensionAndSuffix(
  originalName: string,
  extension: string,
  suffix?: string,
) {
  const fileNamePieces = originalName.split('.');
  fileNamePieces[fileNamePieces.length - 2] =
    fileNamePieces[fileNamePieces.length - 2] + (suffix || '');
  fileNamePieces[fileNamePieces.length - 1] = extension;
  return fileNamePieces.join('.');
}

// The compress pages optimize videos for websites, where they usually play
// muted, so the audio is dropped by default.
export async function getDefaultCompressionConfig(
  locale: Locale,
): Promise<DimensionsConfig> {
  return getDevicesDictionary(locale).then((devicesTranslation) => ({
    keepAudio: false,
    sizes: {
      [devicesTranslation.mobile]: {
        enabled: true,
        screenWidth: 450,
        sizingType: 'percentage',
        percentage: 100,
        width: 450,
        height: 100,
        iconType: 'mobile',
      },
      [devicesTranslation.tablet]: {
        enabled: true,
        screenWidth: 1050,
        sizingType: 'percentage',
        percentage: 50,
        width: 525,
        height: 100,
        iconType: 'tablet',
      },
      [devicesTranslation.desktop]: {
        enabled: true,
        screenWidth: 1950,
        sizingType: 'percentage',
        percentage: 33.33,
        width: 650,
        height: 100,
        iconType: 'desktop',
      },
    },
  }));
}

export function getDefaultFormatConfig(
  formats: Format[],
  versionName: string,
): FormatConfig {
  return {
    formats: [...formats],
    keepAudio: true,
    resize: false,
    versions: [
      {
        name: versionName,
        type: 'percentage',
        value: { percentage: 100, width: 1920, height: 1080 },
      },
    ],
  };
}
